/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.flow;

import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import io.restassured.response.Response;
import io.restassured.specification.RequestSpecification;
import net.civeira.phylax.integrationtest.features.oauth.fixtures.OidcTestFixtures;

/**
 * Resource indicators (RFC 8707, task 4.7): a registered resource gets a token for it; a foreign or
 * malformed one is {@code invalid_target}; the code exchange and the refresh can only narrow the
 * resources of the grant, and the rotated refresh keeps the whole grant.
 */
@QuarkusTest
class ResourceIndicatorFlowTest extends OidcIntegrationTestBase {

  private static final String TOKEN = "/oauth/openid/" + OidcTestFixtures.TENANT + "/token";
  private static final String AUTH = "/oauth/openid/" + OidcTestFixtures.TENANT + "/auth";
  private static final String RESOURCE = OidcTestFixtures.RESOURCE_URI;

  private static RequestSpecification asClient() {
    return RestAssured.given().auth().preemptive()
        .basic(OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET)
        .contentType(ContentType.URLENC);
  }

  private List<String> audiences(String token) {
    return claimAsList(decodeToken(token).get("aud"));
  }

  @Test
  void clientCredentials_forARegisteredResource() {
    Response response = asClient().formParam("grant_type", "client_credentials")
        .formParam("resource", RESOURCE).post(TOKEN);
    Assertions.assertEquals(200, response.statusCode(), response.getBody().asString());
    Assertions
        .assertTrue(audiences(response.jsonPath().getString("access_token")).contains(RESOURCE));
  }

  @Test
  void foreignOrMalformedResource_isInvalidTarget() {
    for (String resource : List.of("https://evil.example/api", "not a uri", RESOURCE + "#frag")) {
      Response response = asClient().formParam("grant_type", "client_credentials")
          .formParam("resource", resource).post(TOKEN);
      Assertions.assertEquals(400, response.statusCode(), resource);
      Assertions.assertEquals("invalid_target", response.jsonPath().getString("error"), resource);
    }
  }

  @Test
  void refresh_narrowsTheResources_butNeverWidens() {
    Response password = asClient().formParam("grant_type", "password")
        .formParam("username", OidcTestFixtures.USERNAME)
        .formParam("password", OidcTestFixtures.PASSWORD).formParam("scope", "openid")
        .formParam("resource", RESOURCE).formParam("audience", OidcTestFixtures.API_AUDIENCE)
        .post(TOKEN);
    Assertions.assertEquals(200, password.statusCode(), password.getBody().asString());
    String refresh = password.jsonPath().getString("refresh_token");

    Response widened =
        asClient().formParam("grant_type", "refresh_token").formParam("refresh_token", refresh)
            .formParam("resource", "https://other.example/api").post(TOKEN);
    Assertions.assertEquals(400, widened.statusCode());
    Assertions.assertEquals("invalid_target", widened.jsonPath().getString("error"));

    Response narrowed = asClient().formParam("grant_type", "refresh_token")
        .formParam("refresh_token", refresh).formParam("resource", RESOURCE).post(TOKEN);
    Assertions.assertEquals(200, narrowed.statusCode(), narrowed.getBody().asString());
    List<String> aud = audiences(narrowed.jsonPath().getString("access_token"));
    Assertions.assertTrue(aud.contains(RESOURCE));
    Assertions.assertFalse(aud.contains(OidcTestFixtures.API_AUDIENCE));
    Assertions.assertTrue(audiences(narrowed.jsonPath().getString("refresh_token"))
        .contains(OidcTestFixtures.API_AUDIENCE), "The rotated refresh keeps the whole grant");
  }

  @Test
  void codeExchange_onlyForTheAuthorizedResources() {
    Map<String, String> query = Map.of("client_id", OidcTestFixtures.CLIENT_ID, "redirect_uri",
        OidcTestFixtures.REDIRECT_URI, "response_type", "code", "scope", "openid", "state",
        OidcTestFixtures.STATE, "resource", RESOURCE);
    Response login = RestAssured.given().redirects().follow(false).contentType(ContentType.URLENC)
        .queryParams(query).formParam("username", OidcTestFixtures.USERNAME)
        .formParam("password", OidcTestFixtures.PASSWORD).formParam("csid", OidcTestFixtures.CSID)
        .post(AUTH);
    String code = client.extractAuthCode(login);
    Assertions.assertNotNull(code, login.getHeader("Location"));

    Response foreign = asClient().formParam("grant_type", "authorization_code")
        .formParam("code", code).formParam("redirect_uri", OidcTestFixtures.REDIRECT_URI)
        .formParam("resource", "https://api.example/billing").post(TOKEN);
    Assertions.assertEquals(400, foreign.statusCode());
    Assertions.assertEquals("invalid_target", foreign.jsonPath().getString("error"));

    Response exchange = asClient().formParam("grant_type", "authorization_code")
        .formParam("code", code).formParam("redirect_uri", OidcTestFixtures.REDIRECT_URI)
        .formParam("resource", RESOURCE).post(TOKEN);
    Assertions.assertEquals(200, exchange.statusCode(), exchange.getBody().asString());
    Assertions
        .assertTrue(audiences(exchange.jsonPath().getString("access_token")).contains(RESOURCE));
  }

  @Test
  void authorize_withAForeignResource_isInvalidTarget() {
    Response response = RestAssured.given().redirects().follow(false)
        .queryParams(Map.of("client_id", OidcTestFixtures.CLIENT_ID, "redirect_uri",
            OidcTestFixtures.REDIRECT_URI, "response_type", "code", "scope", "openid", "resource",
            "https://evil.example/api"))
        .get(AUTH);
    Assertions.assertEquals(302, response.statusCode());
    Assertions.assertTrue(response.getHeader("Location").contains("error=invalid_target"));
  }
}
